  implements RocketPort
{
  private _model: THREE.Group | null = null;
  private _options: Partial<RocketObjectOptions> = {};
  private _flameMesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial> | null = null;

  // Constructor inherited from SceneObject; no explicit constructor shown

