import * as THREE from "three";
import type {
  SceneObjectContext,
  TweenApplyMode,
} from "../types/engine.types.js";
import type { ISceneObject } from "../types/engine.types.js";
import type { ObjectEffects } from "../types/object.types.js";
import type {
  ShaderManagerRuntimePort,
  ShaderRegistration,
} from "../types/shader.types.js";
import { Helpers } from "../utils/Helpers.js";

export abstract class SceneObject<
  TTweenProps = Record<string, unknown>,
> implements ISceneObject {
  protected _context: SceneObjectContext | null = null;
  protected _disposed = false;
  private readonly _shaderOwnerId = `shader-owner-${Math.random().toString(36).slice(2, 10)}`;
  private _timelineRoot: THREE.Group | null = null;
  private _effects: ObjectEffects = {};
  private _visible = true;
  private _ownedTextures = new Set<THREE.Texture>();

  init(context?: SceneObjectContext): void | Promise<void> {
    if (context) {
      this._context = context;
      return;
    }
    return this.runObject();
  }

  abstract runObject(): void | Promise<void>;

  abstract runUpdate(_deltaTime: number): void;

  getAnimationTarget(): THREE.Object3D | Record<string, unknown> | null {
    return this._timelineRoot;
  }

  getBloomTarget(): THREE.Object3D | null {
    const target = this.getAnimationTarget();
    if (target instanceof THREE.Object3D) return target;
    return this._timelineRoot;
  }

  getTweenApplyMode(): TweenApplyMode {
    return "gsapOnly";
  }

  setEffects(effects: ObjectEffects): void {
    this._effects = { ...effects };
  }

  getEffects(): ObjectEffects {
    return this._effects;
  }

  getBloomEnabled(): boolean {
    return this._effects.bloom?.enabled ?? false;
  }

  protected ensureTimelineRoot(name?: string): THREE.Group | null {
    if (this._timelineRoot) return this._timelineRoot;
    const scene = this._context?.scene;
    if (!scene) return null;
    const root = new THREE.Group();
    if (name) root.name = name;
    scene.add(root);
    this._timelineRoot = root;
    this._applyOptionVisibility();
    return root;
  }

  protected attachToTimelineRoot(obj: THREE.Object3D, rootName?: string): void {
    const root = this.ensureTimelineRoot(rootName);
    if (!root) return;
    if (obj.parent && obj.parent !== root) obj.parent.remove(obj);
    root.add(obj);
  }

  protected resolveAssetPath(assetUrl: string): string {
    const base =
      typeof document !== "undefined"
        ? (document.documentElement?.getAttribute?.("data-base") ?? "")
        : "";
    return `${base}${assetUrl}`.replace(/\/+/g, "/");
  }

  protected getTimelineRoot(): THREE.Group | null {
    return this._timelineRoot;
  }

  protected getShaderManager(): ShaderManagerRuntimePort | null {
    const candidate = this._context?.getObject("env.shaderManager.runtime");
    if (!candidate || typeof candidate !== "object") return null;
    const manager = candidate as unknown as ShaderManagerRuntimePort;
    if (typeof manager.register !== "function") return null;
    return manager;
  }

  protected registerShader(registration: ShaderRegistration): void {
    this.getShaderManager()?.register(registration);
  }

  protected getShaderOwnerId(): string {
    return this._shaderOwnerId;
  }

  protected createShaderKey(suffix: string): string {
    return `${this._shaderOwnerId}.${suffix}`;
  }

  protected releaseShaders(ownerId: string): void {
    this.getShaderManager()?.release(ownerId);
  }

  protected offTimelineRoot(): void {
    if (this._timelineRoot?.parent) {
      this._timelineRoot.parent.remove(this._timelineRoot);
    }
    this._timelineRoot = null;
  }

  setTimelineVars(vars: Partial<TTweenProps>, _kind: "from" | "to"): void {
    if (vars == null || Object.keys(vars as object).length === 0) return;
    const normalized = this.normalizeTimelineVars(
      vars as Record<string, unknown>,
    );
    this.mergeOptionsFromTimeline(normalized as Partial<TTweenProps>);
    this._applyOptionVisibility();
    this.syncFromOptions();
  }

  protected normalizeTimelineVars(
    vars: Record<string, unknown>,
  ): Record<string, unknown> {
    return Helpers.normalizeControlVars(vars);
  }

  protected getOptions(): Record<string, unknown> {
    return {};
  }

  getRuntimeOptions(): Record<string, unknown> {
    return this.getOptions();
  }

  protected mergeOptionsFromTimeline(vars: Partial<TTweenProps>): void {
    const options = this.getOptions();
    if (options && typeof options === "object" && Object.keys(vars as object).length > 0) {
      Object.assign(options, vars);
    }
  }

  protected syncFromOptions(): void {}
  protected abstract applyVisibility(visible: boolean): void;
  protected isAlwaysVisible(): boolean {
    return false;
  }

  setVisibleOn(): void {
    this._setVisibility(true);
  }

  setVisibleOff(): void {
    this._setVisibility(false);
  }

  getVisibleState(): boolean {
    return this._visible;
  }

  private _setVisibility(visible: boolean): void {
    const resolved = this.isAlwaysVisible() ? true : visible;
    this._visible = resolved;
    const options = this.getOptions();
    if (options && typeof options === "object") {
      options.visible = resolved;
    }
    this.applyVisibility(resolved);
  }

  protected _applyOptionVisibility(): void {
    const options = this.getOptions();
    const visible = options.visible;
    if (typeof visible === "boolean") {
      this._setVisibility(visible);
      return;
    }
    if (this.isAlwaysVisible()) this._setVisibility(true);
  }

  dispose(): void {
    if (this._disposed) return;
    this._disposed = true;
    for (const texture of this._ownedTextures) texture.dispose();
    this._ownedTextures.clear();
    this.offTimelineRoot();
    this._context = null;
  }

  get isDisposed(): boolean {
    return this._disposed;
  }
}

