이제 해당 이미지를 바탕으로 수정해줘.

파티클 이미지 스타일로 하는거야 마지막 생명주기가 사라지는건

FADE OUT형식으로 SMOKE 잔잔하게 실사적으로 사라직 ㅔ함녀될더같고




let camera, scene, renderer, cube, bounds, smokeCloud, numParticles, text, blowButton

let isBlowing = false

init()
animate()

function init() {
  stats = new Stats()
  stats.setMode(0)
  stats.domElement.style.position = 'absolute'
  stats.domElement.style.left = '0px'
  stats.domElement.style.top = '0px'
  document.body.appendChild(stats.domElement)

  clock = new THREE.Clock()

  // renderer setup
  renderer = new THREE.WebGLRenderer({
    alpha: true
  })
  renderer.setSize(window.innerWidth, window.innerHeight)
  renderer.setClearColor( 0xffffff, 0 )


  scene = new THREE.Scene()

  // camera position
  camera = new THREE.PerspectiveCamera(
    75,
    window.innerWidth / window.innerHeight,
    1,
    10000
  )
  camera.position.z = 1000
  scene.add(camera)

  // scene lighting
  light = new THREE.DirectionalLight(0xDACCD8, 1.0)
  light.position.set(-1, 0, 1)
  scene.add(light)

  // selection of smoke textures (transparent pngs)
  const smokeImages = [
    'https://i.imgur.com/EtMcQ33.png',
    'https://i.imgur.com/6Z1clIX.png',
    'https://i.imgur.com/YmcB0HL.png',
    'https://s3-us-west-2.amazonaws.com/s.cdpn.io/95637/Smoke-Element.png',
    'https://qassets.netlify.com/images/smoke1.png'
  ]

  THREE.ImageUtils.crossOrigin = ''
  smokeTexture = THREE.ImageUtils.loadTexture(smokeImages[3])
  smokeMaterial = new THREE.MeshLambertMaterial({
    color: 0xF1EBDD,
    emissive: 0xffffff,
    map: smokeTexture,
    transparent: true,
    opacity: 0.7
  })

  smokeGeo = new THREE.PlaneGeometry(500, 500)
  smokeCloud = []

  bounds = {
    x: 500,
    y: 500,
    z: 500
  }
  numParticles = 20

  const cubeSize = 300

  cube = new THREE.Mesh(
    new THREE.BoxGeometry(cubeSize, cubeSize, cubeSize),
    new THREE.MeshBasicMaterial({ color: 0xffffff })
  )

  //scene.add(cube)

  for (p = 0; p < numParticles; p++) {
    const particle = new THREE.Mesh(smokeGeo, smokeMaterial)
    particle.position.set(
      Math.random() * bounds.x - (bounds.x * 0.5),
      Math.random() * bounds.y - (bounds.y * 0.5),
      Math.random() * bounds.z - (bounds.z * 0.6)
    )
    particle.rotation.z = Math.random() * 360
    scene.add(particle)
    smokeCloud.push(particle)
  }


  const textImages = [
    'https://i.imgur.com/jK7O95R.png',
    'https://i.imgur.com/5j4r46A.png',
    'https://i.imgur.com/OWqehUB.png'
  ]

  const textGeo = new THREE.PlaneGeometry(360, 360);
  const textTexture = THREE.ImageUtils.loadTexture(textImages[2]);
  const textMaterial = new THREE.MeshLambertMaterial({
    color: 0xffffff,
    map: textTexture,
    emissive: 0xffffff,
    transparent: true,
    blending: THREE.AdditiveBlending,
    opacity: 1
  })
  text = new THREE.Mesh(textGeo,textMaterial);
  //text.position.y = 500;
  text.position.z = 300;
  scene.add(text);

  document.body.appendChild(renderer.domElement)

