import * as THREE from "three";
import { SceneObject } from "../../core/SceneObject.js";
import type { SceneObjectContext } from "../../types/engine.types.js";
import type { GravityBallsObjectOptions } from "../../types/object.types.js";

interface SphereInfo {
  ID: number;
  color: string;
  radiusStart: number;
  startX: number;
  startY: number;
  startZ: number;
  vx: number;
  vxMult: number;
  vy: number;
  vyMult: number;
  vz: number;
  vzMult: number;
  bounced: boolean;
  gravity: number;
  startGravity: number;
  rotDir: number;
  sphere: THREE.Mesh;
  material: THREE.MeshLambertMaterial;
}

type ResolvedOpts = {
  attachTo: string;
  spawnOffset: { x?: number; y?: number; z?: number };
  floorLevel: number;
  floorDimensions: number;
  radius: number;
  colors: string[];
  dotsPerInterval: number;
  physicsScale: number;
  textureUrl: string;
};

// Scale-deincrement per tick matching original `radius(3) * -0.002 = -0.006`
// Ball lifetime: (1.0 - 0.1) / 0.006 = 150 ticks ≈ 2.25 s
const SHRINK_RATE = -0.006;
// Opacity fade starts at this scale and reaches 0 at the removal threshold (0.1)
const FADE_START_SCALE = 0.5;
// Smoke dissipation constants extracted from rotateSmoke() reference
const SMOKE_Z_DRIFT = 0.002;   // position.z drift per tick when fading
const SMOKE_SPREAD = 1.003;    // x/y spread multiplier per tick when fading

const DEFAULTS = {
  attachTo: "rocket",
  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
  floorLevel: -2.5,
  floorDimensions: 25,
  radius: 0.05,
  colors: ["#bada55", "#bada55", "#bada55", "#bada55"] as string[],
  dotsPerInterval: 5,
  physicsScale: 0.017,
  textureUrl: "",
};

export class GravityBalls extends SceneObject<Record<string, never>> {
  private readonly _balls = new Map<number, SphereInfo>();
  private _idx = 0;
  private _accumMs = 0;
  private readonly _spawnPt = new THREE.Vector3();
  private _opts: GravityBallsObjectOptions = {};
  private _floorMesh: THREE.Mesh | null = null;
  private _geo: THREE.PlaneGeometry | null = null;
  private _texture: THREE.Texture | null = null;
  // Base material template — cloned per ball for independent opacity
  private _baseMat: THREE.MeshLambertMaterial | null = null;

  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
    if (props) this._opts = { ...this._opts, ...props };
    return this;
  }

  protected override getOptions(): Record<string, unknown> {
    return this._opts as Record<string, unknown>;
  }

  override async runObject(): Promise<void> {
    const ctx = this._context;
    if (!ctx) return;

    const o = this._resolve();

    // Load smoke texture if configured
    if (o.textureUrl && ctx.loadTexture) {
      try {
        this._texture = await ctx.loadTexture(this.resolveAssetPath(o.textureUrl));
      } catch {
        // Texture load failed — fall back to flat color
      }
    }

    // PlaneGeometry: each ball is a textured quad (diameter = radius * 2)
    this._geo = new THREE.PlaneGeometry(o.radius * 2, o.radius * 2);

    this._baseMat = new THREE.MeshLambertMaterial({
      color: 0xffffff,
      emissive: 0x888888,
      map: this._texture ?? null,
      transparent: true,
      depthWrite: false,
      opacity: 0.8,
    });

    const floorGeo = new THREE.BoxGeometry(o.floorDimensions, 0.05, o.floorDimensions);
    const floorMat = new THREE.MeshLambertMaterial({
      color: "#000000",
      depthWrite: false,
      transparent: true,
      opacity: 0.2,
    });
    this._floorMesh = new THREE.Mesh(floorGeo, floorMat);
    this._floorMesh.position.y = o.floorLevel - o.radius / 2;
    ctx.scene.add(this._floorMesh);

    this._applyOptionVisibility();
  }

  override runUpdate(delta: number): void {
    const ctx = this._context;
    if (!ctx || this._disposed) return;

    this._accumMs += delta * 1000;
    if (this._accumMs >= 15) {
      this._accumMs -= 15;
      this._tick(ctx);
    }

    const q = ctx.camera.quaternion;
    this._balls.forEach(b => { b.sphere.quaternion.copy(q); });
  }

  private _tick(ctx: SceneObjectContext): void {
    const o = this._resolve();

    if (o.attachTo) {
      const rkt = ctx.getObject(o.attachTo);
      if (rkt instanceof THREE.Object3D) {
        rkt.getWorldPosition(this._spawnPt);
        this._spawnPt.x += o.spawnOffset.x ?? 0;
        this._spawnPt.y += o.spawnOffset.y ?? 0;
        this._spawnPt.z += o.spawnOffset.z ?? 0;
      }
    }

    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o);

    const dead: number[] = [];
    this._balls.forEach((b, id) => { if (this._step(b, o)) dead.push(id); });
    for (const id of dead) this._balls.delete(id);
  }

  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts): void {
    const geo = this._geo;
    const baseMat = this._baseMat;
    if (!geo || !baseMat) return;

    const s = o.physicsScale;
    // Clone base material so each ball controls opacity independently
    const ballMat = baseMat.clone();

    const isXNeg = this._rnd(1, 2) === 1;
    const isZNeg = this._rnd(1, 2) === 1;
    let sy = this._spawnPt.y;
    if (sy < o.floorLevel - o.radius / 2) sy = o.floorLevel - o.radius / 2;

    const mesh = new THREE.Mesh(geo, ballMat);
    // Random initial rotation so smoke planes don't all look identical
    mesh.rotation.z = Math.random() * Math.PI * 2;

    const info: SphereInfo = {
      ID: ++this._idx,
      color: o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0],
      radiusStart: o.radius,
      startX: this._spawnPt.x,
      startY: sy,
      startZ: this._spawnPt.z,
      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
      vxMult: this._rnd(10, 20) * 0.15,
      vy: this._rnd(-10, 20) * s,
      vyMult: this._rnd(4, 6) * -0.1,
      vz: isZNeg ? this._rnd(-25, 25) * -0.4 * s : this._rnd(-25, 25) * 0.4 * s,
      vzMult: this._rnd(10, 20) * 0.1,
      bounced: false,
      startGravity: 10 * s,
      gravity: 10 * s,
      // Random rotation speed ±0.003–0.009 rad/tick (≈ delta * 0.4 from reference)
      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
      sphere: mesh,
      material: ballMat,
    };

    ctx.scene.add(mesh);
    this._balls.set(info.ID, info);
  }

  // Returns true when the ball should be removed
  private _step(b: SphereInfo, o: ResolvedOpts): boolean {
    const sp = b.sphere;

    sp.scale.x += SHRINK_RATE;
    sp.scale.y += SHRINK_RATE;
    sp.scale.z += SHRINK_RATE;

    b.startX += b.vx * 0.6;
    b.startY -= b.vy * 0.5;
    b.startZ -= b.vz * 0.6;
    sp.position.x = b.startX;
    sp.position.y = b.startY;
    sp.position.z = b.startZ;

    if (sp.position.y < o.floorLevel - b.radiusStart / 2) {
      if (!b.bounced) {
        b.vx *= b.vxMult;
        b.vz *= b.vzMult;
      } else {
        b.vx *= 0.95;
        b.vz *= 0.95;
      }

      const h = o.floorDimensions / 2;
      const outOfBounds =
        sp.position.x > h || sp.position.x < -h ||
        sp.position.z > h || sp.position.z < -h;

      if (!outOfBounds) {
        b.vy *= b.vyMult;
        sp.position.y = o.floorLevel + b.radiusStart * sp.scale.x;
        b.startY = sp.position.y;
      } else {
        b.gravity = b.startGravity / 4;
        b.startY -= b.vy * 0.01;
        sp.position.y = b.startY + (20 * o.physicsScale - b.radiusStart * sp.scale.x);
      }
      b.bounced = true;
    }

    b.vy += b.gravity;

    // Always rotate slowly (smoke drift effect)
    sp.rotation.z += b.rotDir;

    // Fade phase: opacity + smoke dissipation (z-drift + subtle x/y spread)
    if (sp.scale.y < FADE_START_SCALE) {
      b.material.opacity = Math.max(0, (sp.scale.y - 0.1) / (FADE_START_SCALE - 0.1));
      sp.position.z -= SMOKE_Z_DRIFT;
      b.startX *= SMOKE_SPREAD;
      b.startY *= SMOKE_SPREAD;
    }

    if (sp.scale.y <= 0.1) {
      this._context?.scene.remove(sp);
      b.material.dispose();
      return true;
    }
    return false;
  }

  protected override applyVisibility(visible: boolean): void {
    if (this._floorMesh) this._floorMesh.visible = visible;
    this._balls.forEach(b => { b.sphere.visible = visible; });
  }

  override dispose(): void {
    if (this._disposed) return;
    const scene = this._context?.scene;

    if (this._floorMesh) {
      scene?.remove(this._floorMesh);
      this._floorMesh.geometry.dispose();
      (this._floorMesh.material as THREE.Material).dispose();
      this._floorMesh = null;
    }

    this._balls.forEach(b => {
      scene?.remove(b.sphere);
      b.material.dispose();
    });
    this._balls.clear();

    this._geo?.dispose();
    this._geo = null;
    this._baseMat?.dispose();
    this._baseMat = null;
    // Texture is owned by the engine's texture cache via ctx.loadTexture — do not dispose

    super.dispose();
  }

  private _resolve(): ResolvedOpts {
    const o = this._opts;
    return {
      attachTo: o.attachTo ?? DEFAULTS.attachTo,
      spawnOffset: o.spawnOffset ?? DEFAULTS.spawnOffset,
      floorLevel: o.floorLevel ?? DEFAULTS.floorLevel,
      floorDimensions: o.floorDimensions ?? DEFAULTS.floorDimensions,
      radius: o.radius ?? DEFAULTS.radius,
      colors: (o.colors && o.colors.length > 0) ? o.colors : DEFAULTS.colors,
      dotsPerInterval: o.dotsPerInterval ?? DEFAULTS.dotsPerInterval,
      physicsScale: o.physicsScale ?? DEFAULTS.physicsScale,
      textureUrl: o.textureUrl ?? DEFAULTS.textureUrl,
    };
  }

  // Original random(min, max) = Math.floor(Math.random() * max) + min
  private _rnd(min: number, max: number): number {
    return Math.floor(Math.random() * max) + min;
  }
}

import { Rocket } from "../objects/rocket/Rocket.js";
import { JetEngine } from "../objects/rocket/JetEngine.js";
import { GravityBalls } from "../objects/main/GravityBalls.js";
import { Background } from "../objects/env/Background.js";
import { CloudPlane } from "../objects/env/CloudPlane.js";
import { Ground } from "../objects/main/Ground.js";
import { Light } from "../objects/env/SceneLights.js";
import { Earth } from "../objects/shared/Earth.js";
import { Planet } from "../objects/shared/Planet.js";
import { Astronaut } from "../objects/sub/Astronaut.js";
import { AboutTerrian } from "../objects/sub/AboutTerrian.js";
import { TransitionVeil } from "../objects/sub/TransitionVeil.js";
import { Window } from "../objects/main/Window.js";
import type { Engine } from "../core/Engine.js";
import type { SceneObject } from "../core/SceneObject.js";
import type { PageConfig } from "../types/core.types.js";
import {
  rocket,
  jetEngine,
  gravityBalls,
  mainBackground,
  aboutBackground,
  cloud,
  cloud2,
  cloud3,
  cloud4,
  cloud5,
  cloud6,
  ground,
  planet,
  sceneLights,
  earth,
  astronaut,
  sceneTransitionVeil,
  terrian,
  windowObj,
} from "../core/setup.js";
import type {
  SceneLightsObjectOptions,
  ObjectOptionsByKey,
} from "../types/object.types.js";
import type {
  ObjectFactoryRegistry,
  ObjectRegistrationSpec,
  ISetup,
} from "../types/runtime.types.js";
import { ObjectConfigRuntime } from "../runtime/ObjectConfigRuntime.js";

function createSetOptionsSpec(
  id: keyof ObjectOptionsByKey,
  create: () => SceneObject,
): ObjectRegistrationSpec {
  return {
    id,
    create,
    applyOptions: (instance, options) => {
      const target = instance as { setOptions?: (props: unknown) => unknown };
      if (typeof target.setOptions === "function") {
        target.setOptions(options);
      }
    },
  };
}

function createDefaultRegistry(): ObjectFactoryRegistry {
  return {
    [rocket]: createSetOptionsSpec(rocket, () => new Rocket()),
    [jetEngine]: createSetOptionsSpec(jetEngine, () => new JetEngine()),
    [gravityBalls]: createSetOptionsSpec(gravityBalls, () => new GravityBalls()),
    [mainBackground]: createSetOptionsSpec(
      mainBackground,
      () => new Background(mainBackground),
    ),
    [aboutBackground]: createSetOptionsSpec(
      aboutBackground,
      () => new Background(aboutBackground),
    ),
    [cloud]: createSetOptionsSpec(
      cloud,
      () => new CloudPlane(),
    ),
    [cloud2]: createSetOptionsSpec(
      cloud2,
      () => new CloudPlane(),
    ),
    [cloud3]: createSetOptionsSpec(
      cloud3,
      () => new CloudPlane(),
    ),
    [cloud4]: createSetOptionsSpec(
      cloud4,
      () => new CloudPlane(),
    ),
    [cloud5]: createSetOptionsSpec(
      cloud5,
      () => new CloudPlane(),
    ),
    [cloud6]: createSetOptionsSpec(
      cloud6,
      () => new CloudPlane(),
    ),
    [ground]: createSetOptionsSpec(ground, () => new Ground()),
    [planet]: createSetOptionsSpec(planet, () => new Planet()),
    [sceneLights]: {
      id: sceneLights,
      create: () => new Light(),
      applyOptions: (instance, options) => {
        const target = instance as {
          setOptions?: (
            props: Partial<SceneLightsObjectOptions> | undefined,
          ) => unknown;
        };
        target.setOptions?.(
          options as Partial<SceneLightsObjectOptions> | undefined,
        );
      },
    },
    [earth]: createSetOptionsSpec(earth, () => new Earth()),
    [astronaut]: createSetOptionsSpec(astronaut, () => new Astronaut()),
    [sceneTransitionVeil]: createSetOptionsSpec(
      sceneTransitionVeil,
      () => new TransitionVeil(),
    ),
    [terrian]: createSetOptionsSpec(terrian, () => new AboutTerrian()),
    [windowObj]: createSetOptionsSpec(windowObj, () => new Window()),
  };
}

export class ObjectSetup implements ISetup<
  [Engine, PageConfig],
  Promise<void>
> {
  private readonly _registry = new Map<string, ObjectRegistrationSpec>();
  private readonly _configRuntime = new ObjectConfigRuntime();
  private _disposed = false;
  private static readonly _ENV_ALIAS_BY_OBJECT_ID: Readonly<
    Partial<Record<keyof ObjectOptionsByKey, string>>
  > = {
    [sceneLights]: "env.light",
  };

  constructor(registry: ObjectFactoryRegistry = createDefaultRegistry()) {
    for (const [id, spec] of Object.entries(registry)) {
      this._registry.set(id, spec);
    }
  }

  registerFactory(id: string, spec: ObjectRegistrationSpec): void {
    this._registry.set(id, spec);
  }

  register(id: string, spec: ObjectRegistrationSpec): void {
    this.registerFactory(id, spec);
  }

  async init(engine: Engine, pageConfig: PageConfig): Promise<void> {
    if (this._disposed) return;
    for (const [id, spec] of this._getEnabledSpecs(pageConfig)) {
      const object = this._createConfiguredObject(
        spec,
        pageConfig.objectOptions,
        pageConfig.initialState,
      );
      await engine.setObject(id, object);
      this._registerEnvironmentAlias(engine, id as keyof ObjectOptionsByKey);
    }
  }

  dispose(): void {
    if (this._disposed) return;
    this._disposed = true;
    this._registry.clear();
  }

  private _getEnabledSpecs(
    pageConfig: PageConfig,
  ): Array<[string, ObjectRegistrationSpec]> {
    const enabledSpecs: Array<[string, ObjectRegistrationSpec]> = [];
    for (const [id, enabled] of Object.entries(pageConfig.objects)) {
      if (!enabled) continue;
      const spec = this._registry.get(id);
      if (!spec) continue;
      enabledSpecs.push([id, spec]);
    }
    return enabledSpecs;
  }

  private _createConfiguredObject(
    spec: ObjectRegistrationSpec,
    pageOptions: PageConfig["objectOptions"] | undefined,
    initialState: PageConfig["initialState"] | undefined,
  ): SceneObject {
    const object = spec.create();
    const resolvedConfig = this._configRuntime.resolve(
      spec.id,
      pageOptions,
      initialState,
    );
    spec.applyOptions?.(object, resolvedConfig.options);
    if (resolvedConfig.effects && typeof object.setEffects === "function") {
      object.setEffects(resolvedConfig.effects);
    }
    return object;
  }

  private _registerEnvironmentAlias(
    engine: Engine,
    objectId: keyof ObjectOptionsByKey,
  ): void {
    const envAlias = ObjectSetup._ENV_ALIAS_BY_OBJECT_ID[objectId];
    if (!envAlias) return;
    const target = engine.getObjectById(objectId as string);
    if (!target || typeof target !== "object") return;
    engine
      .getScene()
      .registerObject(envAlias, target as Record<string, unknown>);
  }
}

