interface SmokeParticle {
  ID: number;
  totalTicks: number;
  tick: number;
  birthEnd: number;
  deathStart: number;
  peakOpacity: number;
  vx: number;
  vy: number;
  vz: number;
  rotSpeed: number;
  scalePerTick: number;
  sprite: THREE.Sprite;
